package com.sayanthrock.githubrock.data.settings

import android.content.Context
import androidx.datastore.preferences.core.*
import androidx.datastore.preferences.preferencesDataStore
import dagger.hilt.android.qualifiers.ApplicationContext
import javax.inject.Inject
import javax.inject.Singleton
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map

private val Context.dataStore by preferencesDataStore(name="github_rock_preferences")
enum class ThemeMode{System,Light,Dark;companion object{fun fromStored(v:String?)=entries.firstOrNull{it.name==v}?:System}}
enum class ThemeStyle{Clean,LiquidGlass,Studio,Midnight,Aurora,HighContrast,Obsidian;companion object{fun fromStored(v:String?)=entries.firstOrNull{it.name==v}?:Clean}}
enum class AccentColor{DefaultGitHubRock,Red,Orange,Yellow,Green,Teal,Cyan,Blue,Indigo,Purple,Pink;companion object{fun fromStored(v:String?)=when(v){"Violet"->Purple;"Emerald"->Green;"Rose"->Pink;"Coral"->Red;"Amber"->Yellow;else->entries.firstOrNull{it.name==v}?:DefaultGitHubRock}}}
enum class DisplaySize{Small,Standard,Large;companion object{fun fromStored(v:String?)=entries.firstOrNull{it.name==v}?:Standard}}
enum class FontSize{Small,Default,Large;companion object{fun fromStored(v:String?)=entries.firstOrNull{it.name==v}?:Default}}
enum class FontWeightStyle{Light,Default,Bold;companion object{fun fromStored(v:String?)=entries.firstOrNull{it.name==v}?:Default}}
enum class AppFontFamily{SystemSans,Serif,Monospace;companion object{fun fromStored(v:String?)=entries.firstOrNull{it.name==v}?:SystemSans}}
enum class LoadingStyle{Spinner,Linear,Pulse,Skeleton,Liquid,Orbit,Shimmer,Morph;companion object{fun fromStored(v:String?)=entries.firstOrNull{it.name==v}?:Spinner}}
enum class AnimationStyle{Liquid,Spring,Cinematic,Magnetic,Dynamic;companion object{fun fromStored(v:String?)=entries.firstOrNull{it.name==v}?:Spring}}
enum class CodeColorStyle{Classic,Ocean,Sunset,Monochrome,GitHub;companion object{fun fromStored(v:String?)=entries.firstOrNull{it.name==v}?:Classic}}
enum class LogDisplayStyle{Dialog,Terminal;companion object{fun fromStored(v:String?)=entries.firstOrNull{it.name==v}?:Terminal}}
enum class NavigationBarStyle{FloatingCapsule,Classic,Minimal,Glass,Compact;companion object{fun fromStored(v:String?)=entries.firstOrNull{it.name==v}?:FloatingCapsule}}

data class AppearancePreferences(val themeMode:ThemeMode=ThemeMode.System,val themeStyle:ThemeStyle=ThemeStyle.Clean,val accentColor:AccentColor=AccentColor.DefaultGitHubRock,val customAccentHex:String="",val recentAccentColors:List<String>=emptyList(),val displaySize:DisplaySize=DisplaySize.Standard,val fontSize:FontSize=FontSize.Default,val fontWeight:FontWeightStyle=FontWeightStyle.Default,val fontFamily:AppFontFamily=AppFontFamily.SystemSans,val loadingStyle:LoadingStyle=LoadingStyle.Spinner,val animationStyle:AnimationStyle=AnimationStyle.Spring,val codeColorStyle:CodeColorStyle=CodeColorStyle.Classic,val logDisplayStyle:LogDisplayStyle=LogDisplayStyle.Terminal,val navigationBarStyle:NavigationBarStyle=NavigationBarStyle.FloatingCapsule,val dynamicColor:Boolean=true,val trueBlack:Boolean=false,val showImages:Boolean=true,val workflowPreview:Boolean=true,val workflowStepDetails:Boolean=true,val statusColors:Boolean=true,val actionsControls:Boolean=true,val repositoryManager:Boolean=true,val fileTools:Boolean=true,val compactCards:Boolean=false,val reduceMotion:Boolean=false)

@Singleton class AppPreferences @Inject constructor(@ApplicationContext private val context:Context){
 val appearance:Flow<AppearancePreferences>=context.dataStore.data.map{p->AppearancePreferences(ThemeMode.fromStored(p[THEME_MODE]),ThemeStyle.fromStored(p[THEME_STYLE]),AccentColor.fromStored(p[ACCENT_COLOR]),p[CUSTOM_ACCENT_HEX].orEmpty(),p[RECENT_ACCENT_COLORS].orEmpty().toList().take(MAX_RECENT_ACCENTS),DisplaySize.fromStored(p[DISPLAY_SIZE]),FontSize.fromStored(p[FONT_SIZE]),FontWeightStyle.fromStored(p[FONT_WEIGHT]),AppFontFamily.fromStored(p[FONT_FAMILY]),LoadingStyle.fromStored(p[LOADING_STYLE]),AnimationStyle.fromStored(p[ANIMATION_STYLE]),CodeColorStyle.fromStored(p[CODE_COLOR_STYLE]),LogDisplayStyle.fromStored(p[LOG_DISPLAY_STYLE]),NavigationBarStyle.fromStored(p[NAVIGATION_BAR_STYLE]),p[DYNAMIC_COLOR]?:true,p[TRUE_BLACK]?:false,p[SHOW_IMAGES]?:true,p[WORKFLOW_PREVIEW]?:true,p[WORKFLOW_STEP_DETAILS]?:true,p[STATUS_COLORS]?:true,p[ACTIONS_CONTROLS]?:true,p[REPOSITORY_MANAGER]?:true,p[FILE_TOOLS]?:true,p[COMPACT_CARDS]?:false,p[REDUCE_MOTION]?:false)}
 val dynamicColor:Flow<Boolean>=appearance.map{it.dynamicColor};val biometricLock:Flow<Boolean>=context.dataStore.data.map{it[BIOMETRIC_LOCK]?:false};val favoriteRepositories:Flow<Set<String>>=context.dataStore.data.map{it[FAVORITE_REPOSITORIES].orEmpty()};val repositorySearchHistory:Flow<List<String>>=context.dataStore.data.map{it[REPOSITORY_SEARCH_HISTORY]?.split(HISTORY_SEPARATOR)?.filter(String::isNotBlank).orEmpty()}
 suspend fun setThemeMode(v:ThemeMode)=context.dataStore.edit{it[THEME_MODE]=v.name};suspend fun setThemeStyle(v:ThemeStyle)=context.dataStore.edit{it[THEME_STYLE]=v.name}
 suspend fun setAccentColor(v:AccentColor)=context.dataStore.edit{it[ACCENT_COLOR]=v.name;it[CUSTOM_ACCENT_HEX]="";it[DYNAMIC_COLOR]=false}
 suspend fun setCustomAccentHex(v:String)=context.dataStore.edit{p->val n=normalizeHex(v)?:return@edit;p[CUSTOM_ACCENT_HEX]=n;p[ACCENT_COLOR]=AccentColor.DefaultGitHubRock.name;p[DYNAMIC_COLOR]=false;val r=p[RECENT_ACCENT_COLORS].orEmpty().toMutableList();r.removeAll{it.equals(n,true)};r.add(0,n);p[RECENT_ACCENT_COLORS]=r.take(MAX_RECENT_ACCENTS).toSet()}
 suspend fun setDynamicColor(v:Boolean)=context.dataStore.edit{p->p[DYNAMIC_COLOR]=v;if(v)p[CUSTOM_ACCENT_HEX]=""};suspend fun clearCustomAccent()=context.dataStore.edit{it[CUSTOM_ACCENT_HEX]=""}
 suspend fun setDisplaySize(v:DisplaySize)=context.dataStore.edit{it[DISPLAY_SIZE]=v.name};suspend fun setFontSize(v:FontSize)=context.dataStore.edit{it[FONT_SIZE]=v.name};suspend fun setFontWeight(v:FontWeightStyle)=context.dataStore.edit{it[FONT_WEIGHT]=v.name};suspend fun setFontFamily(v:AppFontFamily)=context.dataStore.edit{it[FONT_FAMILY]=v.name};suspend fun setLoadingStyle(v:LoadingStyle)=context.dataStore.edit{it[LOADING_STYLE]=v.name};suspend fun setAnimationStyle(v:AnimationStyle)=context.dataStore.edit{it[ANIMATION_STYLE]=v.name};suspend fun setCodeColorStyle(v:CodeColorStyle)=context.dataStore.edit{it[CODE_COLOR_STYLE]=v.name};suspend fun setLogDisplayStyle(v:LogDisplayStyle)=context.dataStore.edit{it[LOG_DISPLAY_STYLE]=v.name};suspend fun setNavigationBarStyle(v:NavigationBarStyle)=context.dataStore.edit{it[NAVIGATION_BAR_STYLE]=v.name}
 suspend fun setTrueBlack(v:Boolean)=context.dataStore.edit{it[TRUE_BLACK]=v};suspend fun setShowImages(v:Boolean)=context.dataStore.edit{it[SHOW_IMAGES]=v};suspend fun setWorkflowPreview(v:Boolean)=context.dataStore.edit{it[WORKFLOW_PREVIEW]=v};suspend fun setWorkflowStepDetails(v:Boolean)=context.dataStore.edit{it[WORKFLOW_STEP_DETAILS]=v};suspend fun setStatusColors(v:Boolean)=context.dataStore.edit{it[STATUS_COLORS]=v};suspend fun setActionsControls(v:Boolean)=context.dataStore.edit{it[ACTIONS_CONTROLS]=v};suspend fun setRepositoryManager(v:Boolean)=context.dataStore.edit{it[REPOSITORY_MANAGER]=v};suspend fun setFileTools(v:Boolean)=context.dataStore.edit{it[FILE_TOOLS]=v};suspend fun setCompactCards(v:Boolean)=context.dataStore.edit{it[COMPACT_CARDS]=v};suspend fun setReduceMotion(v:Boolean)=context.dataStore.edit{it[REDUCE_MOTION]=v};suspend fun setBiometricLock(v:Boolean)=context.dataStore.edit{it[BIOMETRIC_LOCK]=v}
 suspend fun addRepositorySearch(q:String){val n=q.trim().replace(HISTORY_SEPARATOR," ").takeIf(String::isNotBlank)?:return;context.dataStore.edit{p->val c=p[REPOSITORY_SEARCH_HISTORY]?.split(HISTORY_SEPARATOR)?.filter(String::isNotBlank).orEmpty();p[REPOSITORY_SEARCH_HISTORY]=buildList{add(n);c.filterNot{it.equals(n,true)}.forEach(::add)}.take(MAX_SEARCH_HISTORY).joinToString(HISTORY_SEPARATOR)}};suspend fun clearRepositorySearchHistory()=context.dataStore.edit{it.remove(REPOSITORY_SEARCH_HISTORY)}
 suspend fun resetAppearance()=context.dataStore.edit{p->p.remove(THEME_MODE);p.remove(THEME_STYLE);p.remove(ACCENT_COLOR);p.remove(CUSTOM_ACCENT_HEX);p.remove(RECENT_ACCENT_COLORS);p.remove(DISPLAY_SIZE);p.remove(FONT_SIZE);p.remove(FONT_WEIGHT);p.remove(FONT_FAMILY);p.remove(LOADING_STYLE);p.remove(ANIMATION_STYLE);p.remove(CODE_COLOR_STYLE);p.remove(LOG_DISPLAY_STYLE);p.remove(NAVIGATION_BAR_STYLE);p.remove(DYNAMIC_COLOR);p.remove(TRUE_BLACK);p.remove(SHOW_IMAGES);p.remove(WORKFLOW_PREVIEW);p.remove(WORKFLOW_STEP_DETAILS);p.remove(STATUS_COLORS);p.remove(ACTIONS_CONTROLS);p.remove(REPOSITORY_MANAGER);p.remove(FILE_TOOLS);p.remove(COMPACT_CARDS);p.remove(REDUCE_MOTION)}
 suspend fun toggleFavoriteRepository(fullName:String){val n=fullName.trim().takeIf{it.count{c->c=='/'}==1}?:return;context.dataStore.edit{p->val s=p[FAVORITE_REPOSITORIES].orEmpty().toMutableSet();val e=s.firstOrNull{it.equals(n,true)};if(e==null)s+=n else s-=e;p[FAVORITE_REPOSITORIES]=s}}
 suspend fun monitoredWorkflowRun(k:String):Long?=context.dataStore.data.first()[longPreferencesKey("workflow_monitor_$k")];suspend fun setMonitoredWorkflowRun(k:String,id:Long)=context.dataStore.edit{it[longPreferencesKey("workflow_monitor_$k")]=id};suspend fun clearMonitoredWorkflowRun(k:String)=context.dataStore.edit{it.remove(longPreferencesKey("workflow_monitor_$k"))}
 private companion object{const val HISTORY_SEPARATOR="\u001F";const val MAX_SEARCH_HISTORY=8;const val MAX_RECENT_ACCENTS=8;val THEME_MODE=stringPreferencesKey("theme_mode");val THEME_STYLE=stringPreferencesKey("theme_style");val ACCENT_COLOR=stringPreferencesKey("accent_color");val CUSTOM_ACCENT_HEX=stringPreferencesKey("custom_accent_hex");val RECENT_ACCENT_COLORS=stringSetPreferencesKey("recent_accent_colors");val DISPLAY_SIZE=stringPreferencesKey("display_size");val FONT_SIZE=stringPreferencesKey("font_size");val FONT_WEIGHT=stringPreferencesKey("font_weight");val FONT_FAMILY=stringPreferencesKey("font_family");val LOADING_STYLE=stringPreferencesKey("loading_style");val ANIMATION_STYLE=stringPreferencesKey("animation_style");val CODE_COLOR_STYLE=stringPreferencesKey("code_color_style");val LOG_DISPLAY_STYLE=stringPreferencesKey("log_display_style");val NAVIGATION_BAR_STYLE=stringPreferencesKey("navigation_bar_style");val DYNAMIC_COLOR=booleanPreferencesKey("dynamic_color");val TRUE_BLACK=booleanPreferencesKey("true_black");val SHOW_IMAGES=booleanPreferencesKey("show_images");val WORKFLOW_PREVIEW=booleanPreferencesKey("workflow_preview");val WORKFLOW_STEP_DETAILS=booleanPreferencesKey("workflow_step_details");val STATUS_COLORS=booleanPreferencesKey("status_colors");val ACTIONS_CONTROLS=booleanPreferencesKey("actions_controls");val REPOSITORY_MANAGER=booleanPreferencesKey("repository_manager");val FILE_TOOLS=booleanPreferencesKey("file_tools");val COMPACT_CARDS=booleanPreferencesKey("compact_cards");val REDUCE_MOTION=booleanPreferencesKey("reduce_motion");val BIOMETRIC_LOCK=booleanPreferencesKey("biometric_lock");val FAVORITE_REPOSITORIES=stringSetPreferencesKey("favorite_repositories");val REPOSITORY_SEARCH_HISTORY=stringPreferencesKey("repository_search_history")}
 private fun normalizeHex(v:String):String?{val c=v.trim().removePrefix("#");if(c.length!=6&&c.length!=8)return null;if(!c.all{it in "0123456789abcdefABCDEF"})return null;return "#${c.uppercase()}"}
}
